import os
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))

# Tests read the graph seed from the fixture generated by services/api
# (`npm run export:graph-seed`), never from MongoDB.
os.environ.setdefault("SEED_DIR", str(Path(__file__).resolve().parent / "fixtures" / "seed"))
os.environ.pop("MONGO_URL", None)
